/**
 * GENERATED — do not edit. Run `node scripts/build-country-shapes.mjs`.
 *
 * Country silhouettes, simplified from the admin-0 boundaries the server
 * bundles for Atlas (geoBoundaries, CC BY 4.0). Each path is Web Mercator,
 * normalised so the longer side is 100 units; `w` and `h` give the shape's
 * own proportions inside that box so it can be drawn without being squashed.
 *
 * 198 countries, built for print at postage-stamp size — islands
 * below 1.2% of the mainland are dropped and each outline is
 * simplified to at most 190 points.
 */

export interface CountryShape {
  /** Path on a 0..100 box, outer rings only. */
  d: string
  /** The shape's own width and height inside that box. */
  w: number
  h: number
  /** Projected bounds `[minX, minY, maxX, maxY]`, for drawing it in place. */
  b: [number, number, number, number]
}

/**
 * Web Mercator, matching the projection the paths were built with. Longitude
 * passes through as degrees; latitude is flipped so y grows downwards like
 * SVG's does.
 */
export function projectMercator(lng: number, lat: number): { x: number; y: number } {
  const clamped = Math.max(-85.05, Math.min(85.05, lat))
  const rad = (clamped * Math.PI) / 180
  return { x: lng, y: -(Math.log(Math.tan(Math.PI / 4 + rad / 2)) * 180) / Math.PI }
}

/**
 * The inverse, for handing the vector map's extent to something that thinks in
 * coordinates — the tile grid, which has to cover exactly what the outlines
 * cover or the picture and the shape it is cut to will not line up.
 */
export function unprojectMercator(x: number, y: number): { lng: number; lat: number } {
  const rad = 2 * (Math.atan(Math.exp((-y * Math.PI) / 180)) - Math.PI / 4)
  return { lng: x, lat: (rad * 180) / Math.PI }
}

/**
 * The same outline, placed in projected world coordinates.
 *
 * The stored path is normalised into its own box; multiplying by the box's span
 * and shifting by its origin puts it back where the country actually is, which
 * is what a map with more than one country on it needs.
 */
export function countryWorldPath(shape: CountryShape): string {
  const span = Math.max(shape.b[2] - shape.b[0], shape.b[3] - shape.b[1]) / 100
  let axis = 0
  return shape.d.replace(/-?\d*\.?\d+/g, m => {
    const isX = axis++ % 2 === 0
    const v = Number(m) * span + (isX ? shape.b[0] : shape.b[1])
    return String(Math.round(v * 1000) / 1000)
  })
}

/*
 * One box per ring of the outline, in the same world coordinates.
 *
 * A country is a single path but not a single landmass. France's is five
 * subpaths, three of which are Kerguelen, French Guiana and New Caledonia, so
 * its `b` covers 221 degrees of longitude and describes nowhere anybody stood.
 * Anything fitting a view to a country needs the pieces, not the aggregate.
 *
 * Cached against the shape object: the boxes are a property of the generated
 * data, and the data does not change while the page is open.
 */
const PARTS = new WeakMap<CountryShape, [number, number, number, number][]>()

export function countryParts(shape: CountryShape): [number, number, number, number][] {
  const cached = PARTS.get(shape)
  if (cached) return cached
  // The same placement `countryWorldPath` does, applied to the numbers rather
  // than to the string.
  const span = Math.max(shape.b[2] - shape.b[0], shape.b[3] - shape.b[1]) / 100
  const parts: [number, number, number, number][] = []
  for (const sub of shape.d.split('M')) {
    const nums = sub.match(/-?\d*\.?\d+/g)
    if (!nums || nums.length < 2) continue
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity
    for (let i = 0; i + 1 < nums.length; i += 2) {
      const x = Number(nums[i]) * span + shape.b[0]
      const y = Number(nums[i + 1]) * span + shape.b[1]
      if (x < minX) minX = x
      if (x > maxX) maxX = x
      if (y < minY) minY = y
      if (y > maxY) maxY = y
    }
    parts.push([minX, minY, maxX, maxY])
  }
  PARTS.set(shape, parts)
  return parts
}

