/** The silhouette for an ISO-3166-1 alpha-2 code, or null if we have none. */
export function countryShape(code: string | null | undefined): CountryShape | null {
  if (!code) return null
  return COUNTRY_SHAPES[code.toUpperCase()] ?? null
}
